(() => {
  addEventListener("message", (event) => {
    const data = event.data;
    if (event.source !== window) return;
    if (typeof data === "string" && data.endsWith("_as_req")) {
      postMessage(data.slice(0, -7) + "_as_res", "*");
    } else if (data && data.type === "as_req_v1" && event.ports[0]) {
      event.ports[0].postMessage({ type: "as_res_v1", key: data.key });
    }
  });
})();
